-- =====================================================================
-- Chronicles RPG - Migration V7: Add Template Columns to Campaign NPCs & Seed NPC Templates
-- =====================================================================

-- 1. Adicionar colunas de suporte a templates e dados de combate JSONB
ALTER TABLE campaign_npcs
    ADD COLUMN data JSONB NOT NULL DEFAULT '{}'::jsonb,
    ADD COLUMN is_template BOOLEAN NOT NULL DEFAULT FALSE;

CREATE INDEX idx_campaign_npcs_template ON campaign_npcs(campaign_id, is_template)
    WHERE is_template = TRUE;

